    csvColumns: [
      "CO CODE",
      "BATCH ID",
      "FILE #",
      "Employee Name",
      "Role",
      "Rate",
      "Reg Hours",
      "Hours 3 code",
      "Hours 3 amount",
      "Earnings 3 Code",
      "Earnings 3 Amount",
      "Earnings 3 Code",
      "Earnings 3 Amount",
    ],
