          var scopeExtra = '';
          if (hasMenuScope) {
            scopeExtra = ' | 历史菜单基数: ' + ((mf.productLines || []).join(', ') || '—') + ' / ' + ((mf.categories || []).join(', ') || '—');
          }
          var metaExtra = '';
          if (c.name) metaExtra += (metaExtra ? ' | ' : '') + '名称: ' + c.name;
          if (c.order != null) metaExtra += (metaExtra ? ' | ' : '') + '顺序: ' + c.order;
          var condExtra = '';
          if (c.conditions && typeof c.conditions === 'object' && Object.keys(c.conditions).length) {
            condExtra = ' | 取值条件: ' + formatConditions(c.conditions);
          }
          var lbl = c.name || c.id || ('计提小费接受方 ' + (ci + 1));
          var wExtra = '';
